test('should use default weights when explicit undefined is provided', () => {
  const miniSearch = new MiniSearch({ fields: ['title'] });
  miniSearch.addAll([{ id: 1, title: 'undefined test document' }]);
  const results = miniSearch.search('test', {
    prefix: true,
    fuzzy: true,
    weights: { fuzzy: undefined, prefix: undefined }
  });
  const defaultResults = miniSearch.search('test', { prefix: true, fuzzy: true });
  expect(results).toEqual(defaultResults);
});

test('should handle null or undefined weights object gracefully', () => {
  const miniSearch = new MiniSearch({ fields: ['title'] });
  miniSearch.addAll([{ id: 1, title: 'null test document' }]);
  const resultsWithNull = miniSearch.search('test', { prefix: true, fuzzy: true, weights: null });
  const resultsWithUndefined = miniSearch.search('test', { prefix: true, fuzzy: true, weights: undefined });
  expect(resultsWithNull).toBeDefined();
  expect(resultsWithUndefined).toBeDefined();
});

