test('should accept partial weights object (type check)', () => {
  const miniSearch = new MiniSearch({ fields: ['title'] });
  miniSearch.search('test', { weights: { fuzzy: 0.5 } });
  miniSearch.search('test', { weights: { prefix: 0.4 } });
  miniSearch.search('test', { weights: {} });
  miniSearch.search('test', { weights: { fuzzy: 0.5, prefix: 0.4 } });
});

