function isValidWeight(value: unknown): value is number {
  return typeof value === 'number' && !isNaN(value) && value >= 0
}

function normalizeWeight(value: number | undefined, defaultValue: number): number {
  if (value === undefined) return defaultValue
  if (!isValidWeight(value)) {
    console.warn(`Invalid weight value: ${value}. Using default: ${defaultValue}`)
    return defaultValue
  }
  return value
}

const fuzzyWeight = normalizeWeight(weights?.fuzzy, defaultSearchOptions.weights.fuzzy)
const prefixWeight = normalizeWeight(weights?.prefix, defaultSearchOptions.weights.prefix)
